type Id = string | number;

const idA: Id = "abc-123";
const idB: Id = 42;

// @ts-expect-error um boolean não pertence à união string | number
const idC: Id = true;

function mostrar(id: Id): string {
  return `ID: ${String(id)}`;
}

console.log(mostrar(idA)); // "ID: abc-123"
console.log(mostrar(idB)); // "ID: 42"
console.log(idC); // true

type Entrada = string | number;

function descrever(valor: Entrada): string {
  // toString() existe em string e em number: é permitido
  const texto = valor.toString();

  // @ts-expect-error toFixed só existe em number, não no lado string da união
  valor.toFixed(2);

  // @ts-expect-error trim só existe em string, não no lado number da união
  valor.trim();

  return texto;
}

console.log(descrever(3.5)); // "3.5"
console.log(descrever("ola")); // "ola"

function formatar(valor: string | number): string {
  if (typeof valor === "string") {
    // aqui dentro valor é string
    return valor.trim().toUpperCase();
  }
  // aqui só sobra number
  return valor.toFixed(2);
}

console.log(formatar("  ola  ")); // "OLA"
console.log(formatar(3.14159)); // "3.14"

type Tamanho = "pequeno" | "medio" | "grande";

function precoBase(tamanho: Tamanho): number {
  if (tamanho === "pequeno") return 2;
  if (tamanho === "medio") return 3;
  return 4;
}

let escolhido: Tamanho = "pequeno";
console.log(precoBase(escolhido)); // 2

escolhido = "grande";
console.log(precoBase(escolhido)); // 4

// @ts-expect-error "enorme" não pertence ao conjunto de valores permitidos
escolhido = "enorme";

const fixo = "medio"; // tipo inferido: "medio"
let solto = "medio"; // tipo inferido: string

console.log(precoBase(fixo)); // 3

// @ts-expect-error solto é string, e string não cabe em Tamanho
console.log(precoBase(solto));

type Largura = number | "auto";

const l1: Largura = 320;
const l2: Largura = "auto";
// @ts-expect-error só o literal "auto" é aceite, não uma string qualquer
const l3: Largura = "cheio";

console.log(l1, l2, l3); // 320 "auto" "cheio"

const METODOS = ["GET", "POST", "DELETE"] as const;
type Metodo = (typeof METODOS)[number]; // "GET" | "POST" | "DELETE"

function pedir(metodo: Metodo): string {
  return `A enviar ${metodo}`;
}

console.log(pedir("POST")); // "A enviar POST"
console.log(METODOS.length); // 3

const soltos = ["GET", "POST"]; // inferido como string[]
// @ts-expect-error sem as const perdem-se os literais: string não cabe em Metodo
const outro: Metodo = soltos[0];
console.log(outro); // "GET"

const config = { modo: "escuro", nivel: 3 } as const;
// @ts-expect-error as const torna todas as propriedades readonly
config.nivel = 4;

type ComId = { id: number };
type ComNome = { nome: string };

type Utilizador = ComId & ComNome; // tem de ter id E nome
type Qualquer = ComId | ComNome; // basta ter id OU nome

const completo: Utilizador = { id: 1, nome: "Ana" };

// @ts-expect-error a interseção exige todos os requisitos: falta nome
const parcial: Utilizador = { id: 2 };

const soId: Qualquer = { id: 3 };
const soNome: Qualquer = { nome: "Rui" };

console.log(completo.id, completo.nome); // 1 "Ana"
console.log(parcial, soId, soNome); // { id: 2 } { id: 3 } { nome: "Rui" }

type Impossivel = string & number; // resolve para never

// @ts-expect-error nenhum valor é atribuível a never
const nada: Impossivel = "ola";
console.log(nada);

type Circulo = { forma: "circulo"; raio: number };
type Quadrado = { forma: "quadrado"; lado: number };
type Figura = Circulo | Quadrado;

function area(figura: Figura): number {
  // forma existe nos dois membros: acesso permitido
  console.log(figura.forma);

  // @ts-expect-error raio só existe no membro Circulo
  console.log(figura.raio);

  if (figura.forma === "circulo") {
    return Math.PI * figura.raio ** 2;
  }
  return figura.lado ** 2;
}

console.log(area({ forma: "quadrado", lado: 3 })); // 9

