type Estado = "ativo" | "inativo" | "suspenso";

function estadoLegivel(estado: Estado): string {
  if (estado === "ativo") return "Conta ativa";
  if (estado === "inativo") return "Conta inativa";
  return "Conta suspensa";
}

const atual: Estado = "suspenso";

console.log(estadoLegivel(atual)); // "Conta suspensa"
console.log(estadoLegivel("ativo")); // "Conta ativa"

// @ts-expect-error "apagado" não pertence ao tipo Estado
console.log(estadoLegivel("apagado"));

type Valor = string | number | boolean;

function formatarValor(valor: Valor): string {
  if (typeof valor === "string") {
    return valor.trim();
  }
  if (typeof valor === "number") {
    return valor.toFixed(2);
  }
  return valor ? "sim" : "nao";
}

console.log(formatarValor("  texto  ")); // "texto"
console.log(formatarValor(7)); // "7.00"
console.log(formatarValor(false)); // "nao"

// @ts-expect-error null não pertence à união Valor
console.log(formatarValor(null));

const MOEDAS = ["EUR", "USD", "GBP"] as const;
type Moeda = (typeof MOEDAS)[number]; // "EUR" | "USD" | "GBP"

const TAXAS: Record<Moeda, number> = {
  EUR: 1,
  USD: 1.08,
  GBP: 0.85,
};

function converterDeEuros(quantia: number, moeda: Moeda): number {
  return Number((quantia * TAXAS[moeda]).toFixed(2));
}

console.log(MOEDAS.length); // 3
console.log(converterDeEuros(100, "USD")); // 108
console.log(converterDeEuros(50, "GBP")); // 42.5

// @ts-expect-error "JPY" não consta do array MOEDAS
console.log(converterDeEuros(10, "JPY"));

type Identificavel = { id: string };
type ComDatas = { criadoEm: Date; atualizadoEm: Date };
type DadosArtigo = { titulo: string; estado: "rascunho" | "publicado" };

type Artigo = Identificavel & ComDatas & DadosArtigo;

function resumir(artigo: Artigo): string {
  const ano = artigo.criadoEm.getUTCFullYear();
  return `${artigo.titulo} (${artigo.estado}, ${ano}) [${artigo.id}]`;
}

const publicado: Artigo = {
  id: "a-1",
  criadoEm: new Date("2024-01-10T00:00:00Z"),
  atualizadoEm: new Date("2024-02-01T00:00:00Z"),
  titulo: "Unioes em TypeScript",
  estado: "publicado",
};

console.log(resumir(publicado)); // "Unioes em TypeScript (publicado, 2024) [a-1]"

// @ts-expect-error falta atualizadoEm: a interseção exige todos os requisitos
const incompleto: Artigo = {
  id: "a-2",
  criadoEm: new Date("2024-03-01T00:00:00Z"),
  titulo: "Rascunho",
  estado: "rascunho",
};

console.log(incompleto.id); // "a-2"

type Vazio = Identificavel & { id: number }; // id: string & number = never
// @ts-expect-error não há valor possível para id: string e number ao mesmo tempo
const impossivel: Vazio = { id: "a-3" };
console.log(impossivel);
